/*
 * A059314  Primes p such that x^26 = 2 has no solution mod p.
 * https://oeis.org/A059314
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy
 * Formula:   not stated
 * Range:     u8 n <= 30, u16 n <= 1000, u32 n <= 1000, u64 n <= 1000,
 *            u128 n <= 1000, big any n
 * Helpers:   gcd64
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/*
 * Formula: a(n) is the n-th prime p for which 2 is not a 26th‑power residue
 * modulo p, i.e. 2^((p-1)/gcd(26,p-1)) mod p ≠ 1.
 * The sequence is generated by a simple prime sieve and a test of the above
 * congruence for each prime.
 */

#include <stdint.h>
#include <stdlib.h>
#include <stdbool.h>
#include "../utils/gcd64.h"

static const size_t SIEVE_LIMIT = 2000000;   /* enough for n up to ~10⁴ */

static uint32_t *prime_list = NULL;   /* array of primes up to SIEVE_LIMIT */
static size_t prime_count   = 0;      /* number of primes collected */

static seq_t  *cache        = NULL;   /* previously computed terms */
static size_t cache_size    = 0;       /* number of stored terms */
static size_t cache_cap     = 0;       /* allocated capacity of cache */

static size_t prime_ptr   = 0;        /* next prime to examine */

/* ---------- helper: compute base^exp mod mod, 64‑bit arithmetic ---------- */
static inline uint64_t mod_pow64(uint64_t base, uint64_t exp, uint64_t mod)
{
    uint64_t result = 1;
    uint64_t cur    = base % mod;
    while (exp != 0) {
        if (exp & 1ULL)
            result = (uint64_t)((__int128)result * cur % mod);
        cur = (uint64_t)((__int128)cur * cur % mod);
        exp >>= 1;
    }
    return result;
}

/* ---------- helper: gcd of two unsigned 64‑bit integers ---------- */

/* ---------- generate primes up to SIEVE_LIMIT (once) ---------- */
static void generate_primes(void)
{
    if (prime_list != NULL) return;      /* already generated */

    size_t limit = SIEVE_LIMIT;
    unsigned char *sieve = (unsigned char *)calloc(limit + 1, 1);
    if (!sieve) return;                  /* allocation failure */

    /* simple sieve of Eratosthenes */
    for (size_t i = 2; i * i <= limit; ++i) {
        if (!sieve[i]) {
            for (size_t j = i * i; j <= limit; j += i)
                sieve[j] = 1;
        }
    }

    /* count primes to allocate array */
    size_t cnt = 0;
    for (size_t i = 2; i <= limit; ++i)
        if (!sieve[i]) ++cnt;

    prime_list = (uint32_t *)malloc(cnt * sizeof(uint32_t));
    if (!prime_list) {
        free(sieve);
        return;
    }

    size_t idx = 0;
    for (size_t i = 2; i <= limit; ++i)
        if (!sieve[i]) prime_list[idx++] = (uint32_t)i;

    prime_count = cnt;
    free(sieve);
}

/* ---------- ensure cache capacity ---------- */
static void resize_cache(void)
{
    if (cache_cap == 0) {
        cache_cap = 16;
        cache     = (seq_t *)malloc(cache_cap * sizeof(seq_t));
    } else {
        cache_cap <<= 1;
        cache = (seq_t *)realloc(cache, cache_cap * sizeof(seq_t));
    }
}

/* ---------- next qualifying prime (tests primes sequentially) ---------- */
static seq_t next_valid_prime(void)
{
    while (prime_ptr < prime_count) {
        uint32_t p = prime_list[prime_ptr++];
        if (p == 2) continue;   /* 2 never qualifies for the sequence */

        uint64_t d   = gcd64(26ULL, (uint64_t)p - 1ULL);
        uint64_t exp = ((uint64_t)p - 1ULL) / d;
        if (mod_pow64(2ULL, exp, (uint64_t)p) != 1ULL)
            return (seq_t)p;
    }
    /* If we ran out of primes, generate a larger sieve (unlikely for n≤10⁴) */
    /* Simple fallback: extend sieve by factor 2 until we find more primes */
    size_t old_limit = SIEVE_LIMIT;
    size_t new_limit = old_limit * 2;
    while (true) {
        unsigned char *sieve = (unsigned char *)calloc(new_limit + 1, 1);
        if (!sieve) return (seq_t)0;   /* allocation failure */

        for (size_t i = 2; i * i <= new_limit; ++i)
            if (!sieve[i])
                for (size_t j = i * i; j <= new_limit; j += i)
                    sieve[j] = 1;

        for (size_t i = prime_count; i <= new_limit; ++i)
            if (!sieve[i]) {
                /* add to prime list */
                uint32_t *tmp = (uint32_t *)realloc(prime_list,
                                                    (prime_count + 1) *
                                                    sizeof(uint32_t));
                if (!tmp) { free(sieve); return (seq_t)0; }
                prime_list = tmp;
                prime_list[prime_count++] = (uint32_t)i;
                prime_ptr = prime_count - 1;   /* next prime to test */
                free(sieve);
                /* continue testing from this prime */
                return next_valid_prime();
            }
        free(sieve);
        new_limit *= 2;   /* increase limit if still insufficient */
    }
}

/* ---------- main sequence function ---------- */
seq_t a(idx_t n)
{
    if (n < 1) return (seq_t)0;   /* undefined for non‑positive indices */

    if (cache_size >= (size_t)n)
        return cache[n - 1];

    /* Ensure data structures are initialized */
    generate_primes();
    if (cache == NULL) resize_cache();

    /* Generate terms until we have at least n terms */
    while (cache_size < (size_t)n) {
        seq_t next = next_valid_prime();
        if (next == (seq_t)0) break;   /* should not happen with sufficient sieve */
        if (cache_size == cache_cap) resize_cache();
        cache[cache_size++] = next;
    }

    return cache[n - 1];
}
